"""Coverage fix for the CDS desk: measure capped blocks at the disclosed cap, and let a firm own level
pick a far branch for 365 days instead of 180.  A soft quote that contradicts the anchor falls through
to the print's upfront instead of being dropped.  Quotes still out-vote the cap.  Two unsigned branches
with no evidence stay unpriced.  Idempotent.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
DESK = ROOT / "aws/shared/cds_desk.py"
TESTS = ROOT / "aws/lambdas/justhodl-cds-desk/tests/run_tests.py"

DESK_PAIRS = [["MIN_CURVE_PRINTS = 1          # uncapped prints per tenor needed for the curve-shape sign test", "MIN_CURVE_PRINTS = 1          # prints per tenor needed for the curve-shape sign test (capped blocks count at the cap)"], ["LONG_ANCHOR_DAYS = 180        # a name's own earlier resolved level may still pick a branch when the two branches are far apart", "LONG_ANCHOR_DAYS = 365        # a name's own earlier resolved level may still pick a branch when the two branches are far apart"], ["        if st == \"soft\":\n            return []   # plausible but contradicts what this name has been trading at: unresolved, not wrong\n", "        # a soft quote that contradicts the anchor is not a quote.  Fall through to the upfront when the\n        # print carries one (the cap is a usable notional).  A bare coupon with no cash still returns [].\n"], ["    # candidates from uncapped derived prints (exact notional)\n    derived = []\n    for t in five:\n        if t[\"capped\"] or t[\"quoted_bp\"] is not None or t[\"price\"] is not None:\n", "    # derived candidates.  A capped block is measured at the disclosed cap (median error ~0.05% of notional).\n    # Quoted prints already returned above, so a cap never out-votes a quote.\n    derived = []\n    for t in five:\n        if t[\"quoted_bp\"] is not None or t[\"price\"] is not None:\n"], ["        if t.get(\"package\") or t[\"capped\"] or t[\"quoted_bp\"] is not None or t[\"price\"] is not None or t[\"kind\"] == \"index\":\n", "        if t.get(\"package\") or t[\"quoted_bp\"] is not None or t[\"price\"] is not None or t[\"kind\"] == \"index\":\n"], ["        if t.get(\"package\") or t[\"capped\"] or t[\"quoted_bp\"] is not None or t[\"price\"] is not None:\n            continue\n        cs = candidate_spreads(t, rate_pct)\n", "        if t.get(\"package\") or t[\"quoted_bp\"] is not None or t[\"price\"] is not None:\n            continue\n        cs = candidate_spreads(t, rate_pct)\n"], ["    the name's own last resolved level within 180 days, usable only when the branches sit far apart ('trailing_long') >", "    the name's own last resolved level within 365 days, usable only when the branches sit far apart ('trailing_long') >"], ["\"sign_rule\": \"evidence order: same-day quoted prints > two-coupon intersection > single feasible branch (uncapped) > trailing 7-day anchor > trailing 90-day two-coupon intersection > the name's own resolved level within 180 days (only when the two branches sit >e^1 apart) > index co-movement of the two branches over 150 days (>=20 day-pairs, corr >=0.3 vs <=0; inferred) > curve-shape (>=3y gap, <300bp); nothing else\"", "\"sign_rule\": \"evidence order: same-day quoted prints > two-coupon intersection > single feasible branch (capped blocks counted at the disclosed cap, and they never out-vote a quote) > trailing 7-day anchor > trailing 90-day two-coupon intersection > the name's own resolved level within 365 days (only when the two branches sit >e^1 apart) > index co-movement of the two branches over 150 days (>=20 day-pairs, corr >=0.3 vs <=0; inferred) > curve-shape (>=3y gap, <300bp); nothing else\""]]

TEST_OLD = "    assert set(L.IMF_LAYER_SOURCES) == set(RL.IMF_ARA) | set(RL.IMF_GDD)\n\n\nif __name__ == \"__main__\":\n"
TEST_NEW = "    assert set(L.IMF_LAYER_SOURCES) == set(RL.IMF_ARA) | set(RL.IMF_GDD)\n\n\ndef test_capped_block_is_measured_at_the_cap_and_never_outvotes_a_quote():\n    \"\"\"A block notional is the disclosed cap, not a reason to drop the print.  It still cannot set the anchor when a quote exists.\"\"\"\n    wide = C.normalize_trade(derived_row(900, **{\"Notional amount-Leg 1\": \"5,000,000+\"}), \"sec\")\n    assert wide[\"capped\"] is True and len(C.candidate_spreads(wide, RATE)) == 1\n    anchor, src, quality = C.day_anchor([wide], RATE, None)\n    assert src == \"single_branch\" and quality == \"firm\" and anchor is not None\n    measured = C._measure([wide], RATE, None)\n    assert measured[\"spread_5y\"] is not None and measured[\"anchor_source\"] == \"single_branch\"\n    # two feasible branches on a capped block stay unsigned \u2014 the cap is not a side\n    amb = C.normalize_trade(derived_row(140, **{\"Notional amount-Leg 1\": \"5,000,000+\"}), \"sec\")\n    assert C.day_anchor([amb], RATE, None) == (None, None, None)\n    cand = C._measure([amb], RATE, None)[\"cand\"]\n    assert cand and cand[\"100\"][0] > 100 > cand[\"100\"][1]\n    quote = C.normalize_trade(quoted_row(112), \"sec\")\n    anchor, src, quality = C.day_anchor([wide, quote], RATE, None)\n    assert src == \"quoted\" and anchor == 112\n\n\ndef test_contradicted_soft_quote_falls_through_to_the_upfront():\n    \"\"\"A Spread-Leg 1 value far from the name's anchor is not a quote, but the print's own upfront still has two branches.\"\"\"\n    trade = C.normalize_trade(derived_row(400, coupon_bp=100.0, **{\"Spread-Leg 1\": \"0.01\", \"Spread notation-Leg 1\": \"3\"}), \"sec\")\n    assert C.quote_status(trade, RATE) == \"soft\"\n    cands = C.candidate_spreads(trade, RATE, 1000.0)\n    assert cands and cands[0][1] != \"quoted\"\n    assert any(abs(v - 400) < 8 for v, _b in cands), cands\n    # a bare coupon with no cash, far from the anchor, is still unresolved\n    bare = C.normalize_trade(quoted_row(100), \"sec\")\n    assert C.candidate_spreads(bare, RATE, 1000.0) == []\n\n\ndef test_own_firm_level_anchors_for_a_year_when_branches_are_far():\n    \"\"\"PG&E-shaped: last firm print ~8 months ago, today's two branches far apart.  180 days dropped it; 365 days keeps it.\"\"\"\n    assert C.LONG_ANCHOR_DAYS == 365\n    series = {\n        \"2025-10-15\": {\"n\": 3, \"n5\": 3, \"np\": 3, \"s\": 109.0, \"sb\": \"quoted\", \"q\": 2, \"amb\": 0, \"nm\": 10.0, \"aq\": \"firm\", \"as\": \"quoted\", \"cd\": None},\n        \"2026-10-01\": {\"n\": 4, \"n5\": 4, \"np\": 0, \"s\": None, \"q\": 0, \"amb\": 4, \"nm\": 20.0, \"cd\": {\"500\": [917.0, 190.0]}},\n    }\n    bank = {\"version\": C.VERSION, \"series\": {\"PGE\": series}, \"meta\": {\"PGE\": {\"kind\": \"corp\", \"raw\": \"PG&E\", \"ccy\": {\"USD\": 4}}}, \"entity_map\": {}, \"days\": [\"2025-10-15\", \"2026-10-01\"]}\n    anc = C.anchors_from_bank(bank, \"2026-10-02\")\n    assert anc[\"PGE\"][2] == \"trailing_long\" and anc[\"PGE\"][0] == 109.0\n    # resolved with that anchor: 190 is near 109, 917 is not, and the branches are far enough for an old anchor\n    trade = C.normalize_trade(derived_row(190, coupon_bp=500.0, day=\"2026-10-01\"), \"sec\")\n    spread, basis = C.resolve_spread(trade, RATE, 109.0, far_only=True)\n    assert basis == \"derived\" and spread is not None and abs(spread - 190) < 15\n    stale = {\"version\": C.VERSION, \"series\": {\"PGE\": {\"2025-08-01\": series[\"2025-10-15\"], \"2026-10-01\": series[\"2026-10-01\"]}},\n             \"meta\": bank[\"meta\"], \"entity_map\": {}, \"days\": [\"2025-08-01\", \"2026-10-01\"]}\n    assert \"PGE\" not in C.anchors_from_bank(stale, \"2026-10-02\")\n\n\nif __name__ == \"__main__\":\n"

def apply(path, old, new, label):
    text = path.read_text()
    if new in text:
        print("already", label)
        return 0
    n = text.count(old)
    if n != 1:
        raise SystemExit("%s: expected 1 match, found %d" % (label, n))
    path.write_text(text.replace(old, new, 1))
    print("patched", label)
    return 1

changed = 0
for i, (old, new) in enumerate(DESK_PAIRS):
    changed += apply(DESK, old, new, "desk-%d" % i)
changed += apply(TESTS, TEST_OLD, TEST_NEW, "tests")
text = DESK.read_text()
if "LONG_ANCHOR_DAYS = 365" not in text or "disclosed cap" not in text:
    raise SystemExit("desk markers missing after patch")
if "def test_capped_block_is_measured_at_the_cap_and_never_outvotes_a_quote" not in TESTS.read_text():
    raise SystemExit("test marker missing after patch")
print("cds coverage patch changed", changed)
